INSERT INTO [QATALUM].[X_CRITERIA] ([CRITERIA], [CRITERIA_SQL], [CRITERIA_TYPE], [SQL_BUILD]) VALUES (50032, N'EXEC  QATALUM.P_ACTION_POST_SAVE  @nTrans= <TRANS>', 11, 0)
INSERT INTO [QATALUM].[X_CRITERIA] ([CRITERIA], [CRITERIA_SQL], [CRITERIA_TYPE], [SQL_BUILD]) VALUES (50033, N'EXISTS
(
    SELECT 1
    FROM <DBO>.D_TRANS_INVALID I
    JOIN <DBO>.D_TRANS VT
        ON I.TRANS_VALID = VT.TRANS
    JOIN <DBO>.D_ACTION VA
        ON VT.TRANS = VA.TRANS
	WHERE VA.ACTION_TIME_LIMIT <> D_ACTION.ACTION_TIME_LIMIT
    AND	VA.ACTION_NO = D_ACTION.ACTION_NO
	AND I.TRANS = D_TRANS.TRANS)
AND NOT EXISTS(
  SELECT 1 FROM <DBO>.D_ACTION_REFERENCE R
  WHERE R.TRANS =D_TRANS.TRANS
  AND R.ACTION_NO = D_ACTION.ACTION_NO
  AND  R.REFERENCE IN (53,56)
  AND R.VALUE IS NOT NULL
)', 1, 3)
